const reportFrame = (t) => t.page.frames().find((frame) => frame.url().includes("/generated/"));
const frameSrc = (t) => t.page.evaluate(() => document.querySelector("iframe.report-frame")?.getAttribute("src") ?? null);
const rowTitles = (t) => t.page.evaluate(() => [...document.querySelectorAll('.row[data-scope="tree"] .row-title')].map((node) => node.textContent));
const badge = (t) => t.page.evaluate(() => document.querySelector(".session-badge")?.textContent ?? null);
const dialogTitle = (t) => t.page.waitForSelector(".dialog-title", { timeout: 5000 }).then(() => t.page.evaluate(() => document.querySelector(".dialog-title").textContent), () => null);
// The version 历史版本 shows, its page drawn and swapped in: { id, text (its main's), pending (a frame still loading out of sight) }.
