// The sample with a paragraph of `words` right after PARAGRAPH, as an Agent writes one.
const addAfterParagraph = (text, words) => text.replace(/(<p[^>]*>Agent 先理解材料[^<]*<\/p>)/, (whole) => `${whole}\n      <p>${words}</p>`);
// The bar of the Agent's changes: its words, "" when none shows.
const changesBar = (t) => t.page.evaluate(() => { const bar = document.querySelector(".ge-changes"); return bar && !bar.hidden ? bar.textContent : ""; });
// What the page marks of the Agent's changes: its fills (and the paragraph the first is over), the
// words added, the words taken out shown in the text, the ghosts of deleted blocks, the room made for them.
const diffMarks = (t) => t.page.evaluate(() => {
  const halos = [...document.querySelectorAll('.ge-diff-halo[data-ge-overlay="changes"]')];
  const over = (rect) => [...document.querySelectorAll("main p")].find((node) => { const own = node.getBoundingClientRect(); return own.height > 0 && Math.abs(own.top - rect.top) < 12 && Math.abs(own.bottom - rect.bottom) < 12; })?.textContent ?? null;
  return {
    halos: halos.length, haloOver: halos[0] ? over(halos[0].getBoundingClientRect()) : null,
    added: CSS.highlights.has("ge-diff-add") ? [...CSS.highlights.get("ge-diff-add")].map((range) => range.toString()) : [],
    words: [...document.querySelectorAll("main .ge-diff-del[data-ge-gone-words]")].map((node) => node.getAttribute("data-ge-gone-words")),
    ghosts: [...document.querySelectorAll('.ge-diff-ghost[data-ge-overlay="changes"]')].filter((node) => node.isConnected).map((node) => node.textContent),
    room: document.querySelector("style[data-ge-changes-room]")?.textContent ?? "",
  };
});
const toastText = (t) => t.page.evaluate(() => document.querySelector(".toast.show")?.textContent ?? "");

// ---------- 批注 ----------
// The window widths the scenarios that pin the markers run at, where the page leaves 批注's cards no
// room (page/margin.mjs: from 978px of page, MARGIN.start + column + lane + cardLeast + cardEnd, a laid
// out card kept down to 962; until 2026-11-12 from 1084, so 1280 with the sidebar open and 1024 on a page
// alone had none). A workbench window leaves its page 270px less with the sidebar open: 1200 is 930 of
// page. A page alone is its window: 940. annotateRoom checks both leave no room, with a classic scrollbar
// too (it only takes from the page).
const NO_ROOM = Object.freeze({ workbench: 1200, page: 940 });
const CARDS_FROM = MARGIN.start + MARGIN.column + MARGIN.lane + MARGIN.cardLeast + MARGIN.cardEnd;
// The report frame the workbench shows (not one loading out of sight).
