// 宽表格's document (wideTablesSwitch, wideTablesTools): "wide", a table of twelve columns (#wide12, 839px of
// columns at the default look, wider than the 712px text; its rows' names its own, which a 批注 quotes), a narrow one
// (#narrow3), one of twenty (#wide20, wider than the page's area at 1440), and a table of twelve columns in an open
// disclosure (#inside) and in a highlight block (#panel); with `long`, one of thirty rows (#long) that scrolls in its
// frame. `look`: doc.json's.
async function wideTablesDocument(t, { look = null, long = false } = {}) {
  const months = ["一月", "二月", "三月", "四月", "五月", "六月", "七月", "八月", "九月", "十月", "十一月"];
  const row = (name, seed) => `<tr><td>${name}</td>${months.map((_, i) => `<td>${(1000 + ((seed * 37 + i * 113) % 900) + i * 0.3).toFixed(1).replace(/^(\d)(\d{3})/, "$1,$2")}</td>`).join("")}</tr>`;
  const twelve = (id, rows = ["线上渠道收入", "线下门店收入", "会员续费"]) => `<div class="doc-table-wrap">
      <table class="doc-table" id="${id}">
        <thead><tr><th>项目</th>${months.map((month) => `<th>${month}</th>`).join("")}</tr></thead>
        <tbody>${rows.map((name, index) => row(name, index + 1)).join("")}</tbody>
      </table>
    </div>`;
  const metrics = Array.from({ length: 19 }, (_, i) => `指标 ${i + 1}`);
  const body = `
    <p>这一段正文标出正文栏的左右两边。</p>
    ${twelve("wide12")}
    <div class="doc-table-wrap">
      <table class="doc-table" id="narrow3">
        <thead><tr><th>名称</th><th>数量</th><th>说明</th></tr></thead>
        <tbody><tr><td>甲</td><td>12</td><td>一段说明</td></tr><tr><td>乙</td><td>7</td><td>另一段说明</td></tr></tbody>
      </table>
    </div>
    <div class="doc-table-wrap">
      <table class="doc-table" id="wide20">
        <thead><tr><th>实验</th>${metrics.map((name) => `<th>${name}</th>`).join("")}</tr></thead>
        <tbody>${["候选 A", "候选 B", "共同基线"].map((name, r) => `<tr><td>${name}</td>${metrics.map((_, i) => `<td>${(40 + ((r * 7 + i * 3) % 30) + 0.25 * i).toFixed(2)}</td>`).join("")}</tr>`).join("")}</tbody>
      </table>
    </div>
    <details class="doc-details" open>
      <summary><span class="doc-details-summary-label">折叠块里的宽表</span></summary>
      <div class="doc-details-content">
        ${twelve("inside", ["甲渠道", "乙渠道", "丙渠道"])}
      </div>
    </details>
    <aside class="doc-panel">
      <p>高亮块里的宽表：</p>
      ${twelve("panel", ["丁渠道", "戊渠道"])}
    </aside>
    ${long ? twelve("long", Array.from({ length: 30 }, (_, index) => `第 ${index + 1} 行`)) : ""}
    <p>最后一段正文。</p>`;
  t.newReport("wide", "宽表格");
  const starter = await t.read("wide");
  await t.write(starter.replace(/\n[ \t]*<!-- Starter content:[^\n]*-->\n[ \t]*<section\b[^>]*\sdata-doc-placeholder\b[\s\S]*?<\/section>/, body), "wide");
  if (look) {
    const file = path.join(t.root, "reports", "wide", "doc.json");
    await fs.writeFile(file, `${JSON.stringify({ ...JSON.parse(await fs.readFile(file, "utf8")), look }, null, 2)}\n`);
  }
}

// What a page of wideTablesDocument shows (evaluated in it): the page's width, the column, each table's frame (its
// edges, whether it scrolls sideways, whether it is placed past the text) and its table's width, the look's
// attribute, the edge room (the page editor's), and whether the page was never reloaded (window.__notReloaded).
function wideTablesMeasure() {
  const column = document.querySelector("main.doc-page").getBoundingClientRect();
  const of = (id) => {
    const table = document.getElementById(id);
    const frame = table.closest(".doc-table-wrap");
    const box = frame.getBoundingClientRect();
    return { left: Math.round(box.left * 10) / 10, right: Math.round(box.right * 10) / 10, scrolls: frame.scrollWidth > frame.clientWidth + 1, across: frame.hasAttribute("data-doc-across"), table: Math.round(table.getBoundingClientRect().width * 10) / 10 };
  };
  return {
    width: document.documentElement.clientWidth, column: { left: column.left, right: column.right },
    wide: of("wide12"), narrow: of("narrow3"), widest: of("wide20"), inside: of("inside"), panel: of("panel"),
    attr: document.documentElement.getAttribute("data-doc-tables"),
    edge: parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--ge-edge-room")) || null,
    kept: window.__notReloaded === true,
  };
}

// What the page's annotation tool says of itself (the overlays' snapshot).
const notes = (frame) => frame.evaluate(() => window.__galleryOverlays().annotations);
// The report's annotations.json, parsed, or null.
const noteFile = async (t, slug = "sample") => { const text = await t.file(`reports/${slug}/annotations.json`); return text === null ? null : JSON.parse(text); };
// An annotation as the file holds one, on `quote` in block `block` (`kind`: "text", or "blocks" for the block whole).
const noteOn = (id, block, quote, text, kind = "text") => ({ id, created: "2026-10-23T10:00:00.000Z", updated: "2026-10-23T10:00:00.000Z", text, anchor: kind === "text" ? { kind, blocks: [block], quote, prefix: "", suffix: "" } : { kind, blocks: [block], quote } });
const seedNotes = (t, items) => fs.writeFile(path.join(t.root, "reports", "sample", "annotations.json"), JSON.stringify({ v: 1, items }));
// The middle of a workbench element.
async function centerOf(t, selector) {
  await t.page.waitForSelector(selector, { visible: true, timeout: 5000 });
  return t.page.$eval(selector, (node) => { const rect = node.getBoundingClientRect(); return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }; });
}
async function clickAt(t, selector) {
  const at = await centerOf(t, selector);
  await t.page.mouse.click(at.x, at.y);
  await t.sleep(400);
}
async function hoverAt(t, selector) {
  const at = await centerOf(t, selector);
  await t.page.mouse.move(at.x, at.y, { steps: 3 });
  await t.sleep(300);
}
// An element of the report frame, in the workbench's coordinates (near its left end, at its middle).
async function inFrame(t, frame, selector) {
  const box = await (await frame.frameElement()).boundingBox();
  const at = await frame.$eval(selector, (node) => { const rect = node.getBoundingClientRect(); return { x: rect.left + Math.min(30, rect.width / 2), y: rect.top + rect.height / 2 }; });
  return { x: box.x + at.x, y: box.y + at.y };
}
async function clickIn(t, frame, selector) {
  const at = await inFrame(t, frame, selector);
  await t.page.mouse.click(at.x, at.y);
  await t.sleep(250);
}
async function hoverIn(t, frame, selector) {
  const at = await inFrame(t, frame, selector);
  await t.page.mouse.move(at.x, at.y, { steps: 3 });
  await t.sleep(400);
}
// The format bar's 批注 pressed, 更多 opened for it: an annotation on the words selected.
async function pressNote(t, frame) {
  await clickIn(t, frame, '.ge-format:not([hidden]) [data-tool="more"]');
  await clickIn(t, frame, '.ge-more:not([hidden]) [data-tool="annotate"]:not([hidden])');
}
// Words of the report selected with the mouse (a drag from their first character to their last).
async function dragWords(t, frame, quote) {
  const box = await (await frame.frameElement()).boundingBox();
  const rect = await frame.evaluate((quote) => {
    const walker = document.createTreeWalker(document.querySelector("main"), NodeFilter.SHOW_TEXT);
    for (let node; (node = walker.nextNode());) {
      const at = node.data.indexOf(quote);
      if (at < 0) continue;
      node.parentElement.scrollIntoView({ block: "center" });
      const range = document.createRange();
      range.setStart(node, at);
      range.setEnd(node, at + quote.length);
      const rects = range.getClientRects();
      const first = rects[0], last = rects[rects.length - 1];
      return { x1: first.left + 1, y1: first.top + first.height / 2, x2: last.right - 1, y2: last.top + last.height / 2 };
    }
    return null;
  }, quote);
  if (!rect) throw new Error(`no words ${quote}`);
  await t.page.mouse.move(box.x + rect.x1, box.y + rect.y1);
  await t.page.mouse.down();
  await t.page.mouse.move(box.x + rect.x2, box.y + rect.y2, { steps: 8 });
  await t.page.mouse.up();
  await t.page.mouse.move(box.x + rect.x2 - 80, box.y + rect.y2 + 160); // off the words and the margin
  await t.sleep(450);
}
// A card open on `quote`, from the format bar.
async function annotateCardOpen(t, frame, quote) {
  await dragWords(t, frame, quote);
  await pressNote(t, frame);
}
// A click into words of the report (the caret there).
async function clickWords(t, frame, words) {
  const box = await (await frame.frameElement()).boundingBox();
  const at = await frame.evaluate((words) => {
    const node = [...document.querySelectorAll("main [data-ge-block]")].find((each) => each.textContent.includes(words));
    const rect = node.getBoundingClientRect();
    return { x: rect.left + 20, y: rect.top + 10 };
  }, words);
  await t.page.mouse.click(box.x + at.x, box.y + at.y);
  await t.sleep(300);
}
// An annotation on `quote` with `text`, made as the reader makes one, closed with Enter once saved.
async function annotateWords(t, frame, quote, text) {
  await dragWords(t, frame, quote);
  await pressNote(t, frame);
  await t.type(text);
  await waitFor(t, async () => (await noteFile(t))?.items?.some((item) => item.text === text), 5000);
  await t.press("Enter");
  await t.sleep(200);
}
// The annotation button's list, or null: its rows ({ text, quote }), its actions ({ label, kbd, off })
// and the line it has with none.
const noteList = (t) => t.page.evaluate(() => {
  const list = document.querySelector(".menu.annot-list");
  if (!list) return null;
  const lines = (node) => [...node.querySelectorAll(".mi-line")].map((line) => line.textContent);
  return {
    rows: [...list.querySelectorAll(".menu-scroll .menu-item")].map((node) => ({ text: lines(node)[0] ?? node.querySelector(".mi-label")?.textContent, quote: lines(node)[1] })),
    actions: [...list.querySelectorAll(":scope > .menu-item")].map((node) => ({ label: node.querySelector(".mi-label").textContent, kbd: node.querySelector(".mi-kbd")?.textContent ?? "", off: node.classList.contains("off") })),
    empty: list.querySelector(".menu-empty")?.textContent ?? "",
  };
});
async function noteListRow(t, label) {
  const at = await t.page.evaluate((label) => { const rect = [...document.querySelectorAll(".annot-list .menu-item")].find((node) => node.textContent.includes(label)).getBoundingClientRect(); return { x: rect.left + 40, y: rect.top + rect.height / 2 }; }, label);
  await t.page.mouse.move(at.x, at.y, { steps: 2 });
  await t.page.mouse.click(at.x, at.y);
  await t.sleep(300);
}

// Until `test` holds (polled), or the time is up: whether it held. A question a navigation cut off is
// asked again in the page it brought.
async function waitFor(t, test, timeout = 10000) {
  const until = Date.now() + timeout;
  while (Date.now() < until) {
    try {
      if (await test()) return true;
    } catch (error) {
      if (!/context was destroyed/i.test(error.message)) throw error;
    }
    await t.sleep(150);
  }
  return false;
}

// ---------- the sidebar's columns (sidebarGroups, linkEntry, sidebarDragAcross, addGalleryProject, workspaceColumns, newPlacement, linkFirstInColumn, greyTagColumn) ----------

// The columns the sidebar shows, in its order: [{ id, label, rows: the ids of its top-level rows }].
const sideColumns = (t) => t.page.evaluate(() => [...document.querySelectorAll(".section[data-column]")].map((section) => ({
  id: section.dataset.column, label: section.querySelector(".sec-label")?.textContent ?? null, rows: [...section.querySelectorAll(':scope > .tree > .node > .row[data-scope="tree"]')].map((row) => row.dataset.id),
})));
// A column's ⋯ menu (its heading's button; `right`: a right click on the heading's line): its labels, `label` chosen (none: closed again).
async function sideColumnMenu(t, id, label = null, right = false) {
  if (right) {
    const at = await t.page.evaluate((id) => { const rect = document.querySelector(`.sec-head[data-column="${id}"]`).getBoundingClientRect(); return { x: rect.right - 60, y: rect.top + rect.height / 2 }; }, id);
    await t.page.mouse.click(at.x, at.y, { button: "right" });
  } else await t.page.evaluate((id) => document.querySelector(`.sec-head[data-column="${id}"] .row-act[aria-label="这一栏的操作"]`).click(), id);
  await t.page.waitForSelector(".menu-item", { timeout: 5000 });
  const labels = await t.page.evaluate(() => [...document.querySelectorAll(".menu .mi-label")].map((node) => node.textContent));
  if (label) await t.page.evaluate((label) => [...document.querySelectorAll(".menu-item")].find((item) => item.querySelector(".mi-label")?.textContent === label).click(), label);
  else await t.press("Escape");
  await t.sleep(250);
  return labels;
}
// Where an element of the workbench is: its centre (x, y), top, bottom, left, width.
const sideBox = (t, selector) => t.page.evaluate((selector) => { const rect = document.querySelector(selector).getBoundingClientRect(); return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, top: rect.top, bottom: rect.bottom, left: rect.left, width: rect.width }; }, selector);
// A drag in the sidebar, from one point to another, with the mouse.
async function sideDrag(t, from, to) {
  await t.page.mouse.move(from.x, from.y);
  await t.page.mouse.down();
  await t.page.mouse.move(from.x, from.y + 8, { steps: 3 });
  await t.page.mouse.move(to.x, to.y, { steps: 8 });
  await t.sleep(150);
  await t.page.mouse.up();
  await t.sleep(400);
}

// ---------- the drafts of other workspaces (otherWorkspaceOpen, otherWorkspaceSession, addGalleryProject, agentDraftJoinsTree, workspaceColumns, newPlacement, greyTagColumn) ----------

// Another workspace beside the studio's (<studio>/<folder>: out of the studio's temporary folder, so on its
// registry: a column of the studio's sidebar), named (`name` null: none, called by its folder), with the documents
// gallery new makes there ([slug, title, under?]): { root, id, entry(slug): a draft's entry in the outline,
// file(slug): its doc.html }.
function otherWorkspace(t, folder, name, docs = []) {
  const root = path.join(t.root, ...folder.split("/"));
  t.gallery("init", root, ...(name === null ? [] : ["--name", name]));
  for (const [slug, title, under] of docs) t.gallery("new", "--workspace", root, slug, title, ...(under ? ["--under", under] : []));
  const id = workspaceId(root);
  return { root, id, entry: (slug) => `~${id}/${slug}`, file: (slug) => path.join(root, slug, "doc.html") };
}
// A free port no scenario of this run was given yet: from the top of the run's GALLERY_TEST_PORTS (a studio's
// server takes the first free one from its bottom), else one the system gives.
const handedPorts = new Set();
const portFree = (port) => new Promise((resolve) => {
  const server = net.createServer();
  server.once("error", () => resolve(null));
  server.listen(port, "127.0.0.1", () => { const { port: given } = server.address(); server.close(() => resolve(given)); });
});
async function sparePort() {
  const range = /^(\d+)-(\d+)$/.exec(process.env.GALLERY_TEST_PORTS ?? "");
  if (!range) {
    for (;;) {
      const port = await portFree(0);
      if (port && !handedPorts.has(port)) return handedPorts.add(port), port;
    }
  }
  for (let port = Number(range[2]); port >= Number(range[1]); port--) {
    if (!handedPorts.has(port) && (await portFree(port)) !== null) return handedPorts.add(port), port;
  }
  throw new Error(`No spare port in GALLERY_TEST_PORTS (${process.env.GALLERY_TEST_PORTS})`);
}
// The port a server the studio's starts for another workspace takes: written as that workspace's last port, which it tries first.
// That server stopped (gallery stop), and its Vite cache taken away.
async function stopOther(t, other) {
  await t.blank();
  const registry = JSON.parse((await t.file("data/workspaces.json")) ?? "{}");
  if (registry.workspaces?.some(entry => path.resolve(entry.root) === path.resolve(other.root))) t.gallery("workspaces", "--forget", other.root);
  await t.sleep(800); // let the registry watcher release this project's filesystem watcher
}
// The frame of a draft the workbench shows: a page of another workspace's server (`port`), its kit drawn and its
// editor started (a frame of another origin: puppeteer's), or null when none came in `timeout` (a server started then).
async function draftFrame(t, owner, slug, timeout = 90000) {
  let found = null;
  const came = await waitFor(t, async () => {
    found = t.page.frames().find((frame) => frame.url().startsWith(`${new URL(t.home()).origin}/~${owner.id}/generated/${slug}.html`)) ?? null;
    return Boolean(found) && (await found.evaluate(() => Boolean(document.querySelector("[data-doc-ready]") && document.querySelector("html[data-ge-save]"))).catch(() => false));
  }, timeout);
  return came ? found : null;
}
// A workspace command (POST /__gallery/workspace/<name>) from the workbench's page, with its token.
const workbenchPost = (t, name, body, base = "") => t.page.evaluate(async (name, body, base) => {
  const { token } = await (await fetch("/__gallery/workspace/info")).json();
  const response = await fetch(`${base}/__gallery/workspace/${name}`, { method: "POST", headers: { "Content-Type": "application/json", "X-Gallery-Token": token }, body: JSON.stringify(body) });
  return { status: response.status, body: await response.json() };
}, name, body, base);

// The tabs the browser opens from now on, as it reports them. waiting: how many came and were not
// taken yet; next(): the next one, a page at its address; close(tab): it closed, the page in front
// again; drop(): those waiting closed; stop(): no more watching.
function watchTabs(t) {
  const context = t.page.browserContext();
  const targets = [];
  const heard = (target) => { if (target.type() === "page") targets.push(target); };
  context.on("targetcreated", heard);
  const close = async (tab) => {
    await tab.page.close();
    await t.page.bringToFront();
    await t.sleep(200);
  };
  const tabs = {
    get waiting() { return targets.length; },
    async next(timeout = 5000) {
      if (!(await waitFor(t, () => targets.length > 0, timeout))) throw new Error("No tab opened");
      const target = targets.shift();
      await waitFor(t, () => !["", "about:blank"].includes(target.url()), timeout);
      return { page: await target.page() };
    },
    close,
    async drop() {
      while (targets.length > 0) await close({ page: await targets.shift().page() });
    },
    stop: () => context.off("targetcreated", heard),
  };
  return tabs;
}

// Which of two pages the browser shows, each page's own word for it, once the new tab has settled.
async function sides(opened, opener) {
  await opened.waitForFunction(() => document.readyState === "complete");
  await new Promise((resolve) => setTimeout(resolve, 300));
  return { opened: await opened.evaluate(() => document.visibilityState), opener: await opener.evaluate(() => document.visibilityState) };
}

// Two documents joined by links: `sample`, holding a link of each form, and `target`, holding blocks
// each hidden in its way (far down, in a closed disclosure, a tab not showing, a detail card).
// A long page of jumps for blockLinkBack…: a closed disclosure and a detail card, paragraphs with no id
// (as an Agent writes them) around the one the reader stands at, which holds links to a block far down, to one in the disclosure
// above and to one in the card, and the far block linking to itself and to another document.
async function jumpPages(t) {
  const main = (body) => (text) => text.replace(/<script>[\s\S]*?<\/script>/g, "<script></script>").replace(/<main([^>]*)>[\s\S]*<\/main>/, () => `<main${text.match(/<main([^>]*)>/)[1]}>${body}</main>`);
  t.newReport("target", "目标页");
  await t.agentEdit(main(`
    <header class="doc-header"><h1 class="doc-title">目标页</h1></header>
    <p>目标页的段落。</p>
  `), "target");
  await t.agentEdit(main(`
    <header class="doc-header"><h1 class="doc-title">起点</h1></header>
    <p>开头的段落。</p>
    <details class="doc-details" data-block-id="foldjjjj"><summary><span class="doc-details-summary-label">上面的折叠块</span></summary><div class="doc-details-content"><p data-block-id="infoldjj">折叠块里的段落。</p>${Array.from({ length: 16 }, (_, index) => `<p>折叠块里的第 ${index} 段。</p>`).join("")}</div></details>
    ${Array.from({ length: 30 }, (_, index) => `<p>前面的第 ${index} 段。</p>`).join("\n")}
    <p data-block-id="spotpara">读者停在这里的段落：<a class="jump-down" href="#farjumpp">到下面的块</a>，<a class="jump-fold" href="#infoldjj">到上面的折叠块</a>，<a class="jump-card" href="#incardjj">到卡片里的块</a>。</p>
    ${Array.from({ length: 60 }, (_, index) => `<p>中间的第 ${index} 段。</p>`).join("\n")}
    <p data-block-id="farjumpp">很远的目标段落，<a class="jump-again" href="#farjumpp">再到这里</a>，<a class="jump-away" href="../target/doc.html">到另一页</a>。</p>
    ${Array.from({ length: 30 }, (_, index) => `<p>后面的第 ${index} 段。</p>`).join("\n")}
    <section class="doc-sheet-shell" data-doc-sheets="jumps" aria-label="选项卡" data-block-id="tabsjjjj">
      <div class="doc-sheet-tabs" role="tablist" aria-label="选项卡"><button class="doc-sheet-tab" type="button" data-sheet-tab="one">第一</button><button class="doc-sheet-tab" type="button" data-sheet-tab="two">第二</button></div>
      <div data-doc-sheet="one"><p data-block-id="tabonejj">第一个选项卡的段落，<a class="jump-tab" href="#tabtwojj">到第二个选项卡</a>。</p>${Array.from({ length: 8 }, (_, index) => `<p>第一个选项卡的第 ${index} 段。</p>`).join("")}</div>
      <div data-doc-sheet="two"><p data-block-id="tabtwojj">第二个选项卡的段落。</p></div>
    </section>
    ${Array.from({ length: 20 }, (_, index) => `<p>选项卡后的第 ${index} 段。</p>`).join("\n")}
    <p data-block-id="entryjjj">入口段，<a class="doc-dialog-trigger" href="#cardjj">卡片入口</a>在这里。</p>
    <dialog class="doc-dialog" id="cardjj" aria-labelledby="cardjj-title"><div class="doc-dialog-panel"><header class="doc-dialog-header"><h2 class="doc-dialog-title" id="cardjj-title">卡片</h2><button class="doc-dialog-close" type="button" data-doc-dialog-close aria-label="关闭">×</button></header><div class="doc-dialog-content"><p data-block-id="incardjj">卡片里的段落。</p></div></div></dialog>
  `));
}

// For jumpPages, in `frame()`: stand() scrolls the reader's paragraph 240px down the window, the caret
// in it where the page edits, and says where its top is; spotTop() where it is now; selected() the
// blocks selected.
function jumpProbes(frame) {
  const spotTop = () => frame().evaluate(() => Math.round([...document.querySelectorAll("main p")].find((node) => node.textContent.startsWith("读者停在这里")).getBoundingClientRect().top));
  const stand = async () => {
    await frame().evaluate(() => {
      const spot = [...document.querySelectorAll("main p")].find((node) => node.textContent.startsWith("读者停在这里"));
      scrollTo(0, spot.getBoundingClientRect().top + scrollY - 240);
      const text = spot.firstChild;
      if (spot.isContentEditable && text?.nodeType === 3) {
        spot.focus({ preventScroll: true });
        getSelection().collapse(text, 3);
      }
    });
    await new Promise((done) => setTimeout(done, 300));
    return spotTop();
  };
  const selected = () => frame().evaluate(() => (window.__gallerySelected?.() ?? []).map((node) => node.getAttribute("data-block-id")));
  return { stand, spotTop, selected };
}

