// linkedPages with more of them in a workbench, `sample` shown, long enough to be far down in, and
// `binned` to go to the trash: { address(), start(): the way to `sample` }.
async function morePages(t) {
  const { page } = t;
  await linkedPages(t);
  t.newReport("third", "第三页");
  t.newReport("binned", "将要删除的页");
  const origin = new URL(t.home()).origin;
  await t.agentEdit((text) => text.replace("</main>", `
    <p>更多 <a class="to-third" href="../third/doc.html">到第三页</a> 和 <a class="to-binned" href="../binned/doc.html">到要删的页</a> 和 <a class="by-title" href="${origin}/#${encodeURIComponent(linkOf("binned", "将要删除的页"))}">标题的地址</a> 后文</p>
    ${Array.from({ length: 80 }, (_, index) => `<p>后面的第 ${index} 段。</p>`).join("\n")}
    <p data-block-id="farlinkk">很远的段落 <a class="far-link" href="../target/doc.html">到目标页</a> 后文</p>
    ${Array.from({ length: 20 }, (_, index) => `<p>更后面的第 ${index} 段。</p>`).join("\n")}
  </main>`));
  await page.setViewport({ width: 1280, height: 1100 });
  await openHome(t);
  const start = () => showSample(t);
  await start();
  return { start, address: () => page.evaluate(() => decodeURIComponent(location.hash)) };
}

// A 批注 on a short paragraph of `sample`, in a workbench, a page block in it: what it quotes holds
// the words the file gives the block. Too short for the server to find it in part (EXACT_UNDER), a
// quote of the words the page shows would not be in the file, and the next save would delete it.
async function annotateThroughChip(t) {
  const { page } = t;
  await openHome(t);
  await page.evaluate(() => { location.hash = "sample"; });
  await frameReady(t, "sample");
  const frame = shownFrame(t);
  await frame.evaluate(() => {
    const paragraph = [...document.querySelectorAll("main p")].find((node) => node.textContent.startsWith("见"));
    const range = document.createRange();
    range.selectNodeContents(paragraph);
    paragraph.focus();
    getSelection().removeAllRanges();
    getSelection().addRange(range);
  });
  await t.sleep(450);
  await pressNote(t, frame);
  await t.type("穿过页面块的批注");
  await waitFor(t, async () => (await noteFile(t))?.items?.some((item) => item.text === "穿过页面块的批注"), 5000);
  await t.press("Enter");
  await t.sleep(300);
  const quoted = JSON.stringify((await noteFile(t))?.items ?? []);
  t.check(quoted.includes("短词") && !quoted.includes("新的标题"), "批注: the page reads a page block by the file's words", quoted);
  await typeInFrame(t, frame, "第三段的文字", "第三段的文字", "再写");
  await waitFor(t, async () => (await t.read()).includes("第三段的文字再写"), 8000);
  await t.sleep(600);
  t.check(((await noteFile(t))?.items ?? []).some((item) => item.text === "穿过页面块的批注"), "and it stays with the next save, the server reading the same words");
  await t.agentEdit((text) => text.replace("第三段的文字再写", "第三段的文字"));
  await t.sleep(600);
  await page.goto("about:blank");
}

// The document `slug` shown in the workbench with the block `id` selected.
const arrived = (t, slug, id) => waitFor(t, async () => {
  const frame = shownFrame(t);
  if (!frame?.url().includes(`/generated/${slug}.html`)) return false;
  return frame.evaluate((id) => window.__gallerySelected?.()[0]?.getAttribute("data-block-id") === id, id).catch(() => false);
}, 15000);

async function openHome(t) {
  await t.page.goto(t.home(), { waitUntil: "load" });
  await t.page.waitForSelector('.row[data-scope="tree"]', { timeout: 20000 });
  // A workspace with a custom page opens the head's first page (no page by its slug, 2026-11-09): the first document then, by its row.
  if (await t.page.waitForFunction(() => location.hash.length > 1, { timeout: 5000 }).then(() => t.page.evaluate(() => location.hash.startsWith("#@")), () => false)) {
    await t.page.evaluate(() => document.querySelector('.row[data-scope="tree"]').click());
  }
  await frameReady(t);
}

// The words of the conflict cards a page (or a workbench's frame) holds, "" for none.
const conflictCards = (target) => target.evaluate(() => [...document.querySelectorAll(".ge-conflict")].map((node) => node.textContent).join(" "));

// What a page (or a workbench's frame) shows once it asked of what the page before it kept, an Agent's
// write from what it read before the reader's edits (a text and a block made, as the agentRevert*
// scenarios make them) having put both back: the text a card, the block listed, the list shown.
async function revertShown(t, target, label) {
  await target.waitForSelector(".ge-conflict", { timeout: 10000 }).catch(() => {});
  await target.waitForFunction(() => Boolean(document.querySelector(".ge-panel")?.textContent.includes("读者新写的一段。")), { timeout: 10000 }).catch(() => {});
  const card = await conflictCards(target);
  const listed = await target.evaluate(() => Object.keys(localStorage).filter((key) => key.endsWith(":lost")).map((key) => localStorage.getItem(key)).join(" "));
  const file = await t.read();
  t.check(file.includes("这份页面（AI 重写）") && !file.includes("认真") && !file.includes("读者新写的一段"), `${label}: the file has the Agent's write, which put both back`);
  t.check(card.includes("改回去了") && card.includes("Agent 先认真理解"), `${label}: the text it put back is a card`, card.slice(0, 200));
  t.check(listed.includes("读者新写的一段。") && listed.includes("reverted"), `${label}: the block it took out is listed`, listed.slice(0, 300));
  t.check(await target.evaluate(() => Boolean(document.querySelector(".ge-panel")?.textContent.includes("读者新写的一段。"))), `${label}: and the list shown`);
}

// The report in the workbench's iframe loaded, its editor started and the session connected.
async function frameReady(t, slug = null, timeout = 15000) {
  await t.page.waitForFunction((slug) => {
    const frame = document.querySelector("iframe.report-frame");
    return frame && (!slug || frame.getAttribute("src") === `/generated/${slug}.html`) && frame.contentDocument?.querySelector("[data-doc-ready]")
      && frame.contentDocument.querySelector("html[data-ge-save]");
  }, { timeout }, slug);
  await t.sleep(500);
}

// The workbench's report frame shown (not one loading out of sight beside it, data-pending), or null.
async function visibleFrame(t) {
  for (const frame of t.page.frames()) {
    if (frame === t.page.mainFrame() || frame.isDetached()) continue;
    const element = await frame.frameElement().catch(() => null);
    if (element && (await element.evaluate((node) => node.isConnected && node.classList.contains("report-frame") && !node.hasAttribute("data-pending")).catch(() => false))) return frame;
  }
  return null;
}

// The first block of a page's main, in order, whose top is in the window: its id and how far down the window it stands.
const topBlock = (target) => target.evaluate(() => {
  for (const node of document.querySelectorAll("main [data-block-id]")) {
    const box = node.getBoundingClientRect();
    if (box.height > 0 && box.top >= 0) return { id: node.getAttribute("data-block-id"), at: Math.round(box.top), y: Math.round(scrollY) };
  }
  return null;
});
// How far down the window block `id` stands, or null.
const blockTop = (target, id) => target.evaluate((id) => {
  const node = document.querySelector(`main [data-block-id="${id}"]`);
  return node ? Math.round(node.getBoundingClientRect().top) : null;
}, id);

// From now until seenShown: the workbench's page at `src` as it is shown, once its kit shows it (data-doc-ready):
// `first`, where `selector` stands in its window ({ top, y }: its top, the page's scroll) at the moment its frame
// is shown (the frame no longer data-pending or put in shown, heard by a MutationObserver before that frame is
// drawn), and `frames`, the same in every frame the workbench draws from then on (the scrollKeptSwitch scenarios).
const watchShown = (t, src, selector) => t.page.evaluate(([src, selector]) => {
  cancelAnimationFrame(window.__shownTick);
  window.__shownObserver?.disconnect();
  const state = window.__shown = { first: null, frames: [] };
  const shownFrame = () => [...document.querySelectorAll("iframe.report-frame:not([data-pending])")].find((frame) => frame.getAttribute("src") === src);
  const where = (frame) => {
    const doc = frame?.contentDocument;
    if (!doc?.documentElement?.hasAttribute("data-doc-ready")) return null;
    const node = doc.querySelector(selector);
    return { top: node ? Math.round(node.getBoundingClientRect().top) : null, y: Math.round(frame.contentWindow.scrollY) };
  };
  const look = () => { state.first ??= where(shownFrame()); };
  window.__shownObserver = new MutationObserver(look);
  window.__shownObserver.observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ["data-pending"] });
  const tick = () => {
    const spot = where(shownFrame());
    if (spot) {
      look();
      state.frames.push(spot);
    }
    if (state.frames.length < 300) window.__shownTick = requestAnimationFrame(tick);
  };
  window.__shownTick = requestAnimationFrame(tick);
}, [src, selector]);
const seenShown = (t) => t.page.evaluate(() => {
  cancelAnimationFrame(window.__shownTick);
  window.__shownObserver?.disconnect();
  return window.__shown ?? { first: null, frames: [] };
});

// GALLERY_TEST_SHOTS=<folder>: what the browser draws from now until the function returned is called (CDP's
// screencast, a picture for each frame it sends), kept as <name>-<n>-<ms since the first>.png; without it nothing.
async function screencast(t, folder, name) {
  if (!folder) return async () => 0;
  await fs.mkdir(folder, { recursive: true });
  const cdp = await t.page.createCDPSession();
  const frames = [];
  cdp.on("Page.screencastFrame", ({ data, sessionId, metadata }) => {
    frames.push({ data, at: metadata.timestamp });
    cdp.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
  });
  await cdp.send("Page.startScreencast", { format: "png", everyNthFrame: 1 });
  return async () => {
    await cdp.send("Page.stopScreencast").catch(() => {});
    await cdp.detach().catch(() => {});
    const start = frames[0]?.at ?? 0;
    for (const [index, frame] of frames.entries()) await fs.writeFile(path.join(folder, `${name}-${String(index).padStart(3, "0")}-${Math.round((frame.at - start) * 1000)}ms.png`), Buffer.from(frame.data, "base64"));
    return frames.length;
  };
}

// A custom page shown in the workbench's report area: one frame, at /pages/<slug>, its kit ready (ui.js marks it).
// ---------- a custom page's board (the pageBoard* scenarios) ----------

// The blocks of tests/fixtures/page-blocks/local/ these scenarios name, put into the studio's
// components/local/, and taken by the server's catalog before they go on; dropPageBlocks takes them away.
async function pageBlocks(t, names) {
  for (const name of names) await fs.cp(path.join(projectRoot, "tests", "fixtures", "page-blocks", "local", name), path.join(t.root, "reports", "components", "local", name), { recursive: true });
  const taken = async () => {
    const { packages } = await (await fetch(`${t.home()}__gallery/workspace/components`)).json();
    return names.every((name) => packages.some(({ id, state }) => id === `local/${name}` && state !== "broken"));
  };
  if (!(await waitFor(t, taken, 15000))) {
    const { packages } = await (await fetch(`${t.home()}__gallery/workspace/components`)).json();
    throw new Error(`the server took no ${names.join(", ")}: ${JSON.stringify(packages.map(({ id, state }) => `${id} ${state}`))}`);
  }
}
async function dropPageBlocks(t, names) {
  for (const name of names) await fs.rm(path.join(t.root, "reports", "components", "local", name), { recursive: true, force: true });
}

// local/lanes: the official example local/kanban (the studio's own copy) as a block a page takes too
// (places document and page, a card 6 × 4), its drag the kit's (DocKit.drag).
async function lanesBlock(t) {
  const from = path.join(t.root, "reports", "components", "local", "kanban");
  const to = path.join(t.root, "reports", "components", "local", "lanes");
  await fs.mkdir(to, { recursive: true });
  for (const name of await fs.readdir(from)) {
    if (name === "component.json") continue;
    await fs.writeFile(path.join(to, name), (await fs.readFile(path.join(from, name), "utf8")).replaceAll("local/kanban", "local/lanes"));
  }
  const manifest = JSON.parse(await fs.readFile(path.join(from, "component.json"), "utf8"));
  await fs.writeFile(path.join(to, "component.json"), JSON.stringify({ ...manifest, id: "local/lanes", places: ["document", "page"], card: { w: 6, h: 4 } }, null, 2));
  await waitFor(t, async () => (await (await fetch(`${t.home()}__gallery/workspace/components`)).json()).packages.some(({ id, state }) => id === "local/lanes" && state === "normal"), 15000);
}

// The custom page `slug` (gallery page new), its board holding `cards`: [id, x, y, w, h, block, markup?]
// each, an instance of the block's template where no markup is given; its page.json saying what the default
// home page's says where asked (`defaults`: defaultCards, 恢复默认卡片 and the note of new cards; `hint`: its
// first-open note). Its page.html.
async function boardPage(t, cards, { slug = "home", title = "首页", defaults = false, hint = false } = {}) {
  t.gallery("page", "new", slug, title);
  const file = path.join(t.root, "reports", "pages", slug, "page.html");
  if (defaults || hint) {
    const json = path.join(t.root, "reports", "pages", slug, "page.json");
    await fs.writeFile(json, `${JSON.stringify({ ...JSON.parse(await fs.readFile(json, "utf8")), ...(defaults ? { defaultCards: true } : {}), ...(hint ? { hint: true } : {}) }, null, 2)}\n`);
  }
  const templates = new Map();
  for (const [, , , , , block] of cards) {
    if (!templates.has(block)) templates.set(block, (await fs.readFile(path.join(t.root, "reports", "components", ...block.split("/"), "template.html"), "utf8")).trim());
  }
  const markup = cards.map(([id, x, y, w, h, block, inner]) => `      <section class="gallery-card" data-card-id="${id}" data-x="${x}" data-y="${y}" data-w="${w}" data-h="${h}">\n        ${inner ?? templates.get(block)}\n      </section>\n`).join("");
  await fs.writeFile(file, (await fs.readFile(file, "utf8")).replace('<div class="gallery-board" data-board-id="main">\n', (board) => board + markup));
  return file;
}

// The custom page alone (/pages/<slug>, as gallery page open gives it the Agent), drawn and edited.
async function boardAlone(t, slug = "home") {
  await t.page.goto(`${t.home()}pages/${slug}`, { waitUntil: "load" });
  await t.page.waitForSelector("html[data-doc-drawn]", { timeout: 15000 });
  await t.page.waitForSelector(".ge-board-layer", { timeout: 5000 });
  await t.sleep(300);
}

// Where an element of the page is: its box and its middle (window px), or null.
const boxOf = (t, selector) => t.page.evaluate((selector) => {
  const rect = document.querySelector(selector)?.getBoundingClientRect();
  return rect ? { x: rect.left, y: rect.top, w: rect.width, h: rect.height, cx: rect.left + rect.width / 2, cy: rect.top + rect.height / 2 } : null;
}, selector);
// The board's cell and a cell with its gap, in px.
const boardGrid = (t) => t.page.evaluate(() => {
  const cell = parseFloat(document.querySelector(".gallery-board").style.getPropertyValue("--gallery-cell"));
  return { cell, step: cell + 16 };
});
// The pointer on card `id` (its grip comes, at its top-right corner).
async function hoverCard(t, id) {
  await t.page.evaluate((id) => {
    const card = document.querySelector(`[data-card-id="${id}"]`).getBoundingClientRect();
    if (card.top < 40 || card.bottom > innerHeight - 20) scrollBy(0, card.top < 40 ? card.top - 60 : Math.min(card.top - 60, card.bottom - innerHeight + 60));
  }, id);
  await t.sleep(100);
  const card = await boxOf(t, `[data-card-id="${id}"]`);
  await t.page.mouse.move(card.x + 30, card.y + 30, { steps: 2 });
  await t.sleep(250);
}
// A heatmap's tip near its card's right edge (the user's word of 2026-11-09: a tip there widened the card into
// a sideways scrollbar): the pointer on the first square of the card's last week (`day`, its squares' selector;
// `tip`, its tip's), then what it shows: { shown (open), layer (a popover in the top layer), inWindow, over
// (the tip what the window shows at its middle: over the card), scrolls (the card, or an element in it, that
// scrolls sideways or has grown wider than its box since the pointer came: none), page (the page wider than the
// window), near (the tip's middle, or its arrow, within 12px of the square's middle across, or the tip held at
// the window's edge) }, then { hidden } once the pointer has left the squares.
async function heatmapTip(t, id, day, tip) {
  await hoverCard(t, id);
  // Each element of the card (but the tip): [index, how much wider its content is than its box, a sideways scrollbar, its class].
  const widths = (id, tip) => {
    const card = document.querySelector(`[data-card-id="${id}"]`);
    const node = card.querySelector(tip);
    return [card, ...card.querySelectorAll("*")].map((one, index) => [index, one === node || node?.contains(one) ? 0 : Math.max(0, one.scrollWidth - one.clientWidth),
      one !== node && !node?.contains(one) && /auto|scroll/.test(getComputedStyle(one).overflowX) && one.scrollWidth > one.clientWidth + 1, one.className?.baseVal ?? one.className]);
  };
  const before = await t.page.evaluate(widths, id, tip);
  const square = await t.page.evaluate((id, day) => {
    const boxes = [...document.querySelectorAll(`[data-card-id="${id}"] ${day}`)].map((node) => node.getBoundingClientRect()).filter((box) => box.width > 0);
    const last = Math.max(...boxes.map((box) => Math.round(box.left)));
    const box = boxes.filter((one) => Math.round(one.left) === last).sort((a, b) => a.top - b.top)[0];
    return box ? { x: box.left + box.width / 2, y: box.top + box.height / 2 } : null;
  }, id, day);
  if (!square) return null;
  await t.page.mouse.move(square.x, square.y, { steps: 3 });
  await t.sleep(300);
  const during = await t.page.evaluate(widths, id, tip);
  const seen = await t.page.evaluate((id, tip, square) => {
    const card = document.querySelector(`[data-card-id="${id}"]`);
    const node = card.querySelector(tip);
    const box = node?.getBoundingClientRect();
    const shown = Boolean(node) && (node.matches(":popover-open") || (!node.hidden && getComputedStyle(node).display !== "none"));
    // what the window shows at its middle (the tip lets the pointer through: taken for this alone)
    if (node) node.style.pointerEvents = "auto";
    const hit = box ? document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2) : null;
    if (node) node.style.pointerEvents = "";
    const arrow = node ? parseFloat(getComputedStyle(node).getPropertyValue("--gallery-heatmap-arrow")) : NaN;
    const middle = box ? (Number.isFinite(arrow) ? box.left + arrow : box.left + box.width / 2) : NaN;
    return {
      shown, layer: Boolean(node?.matches(":popover-open")),
      inWindow: Boolean(box) && box.left >= 0 && box.right <= innerWidth && box.top >= 0 && box.bottom <= innerHeight,
      over: Boolean(hit && node.contains(hit)),
      page: document.documentElement.scrollWidth > innerWidth,
      near: Boolean(box) && (Math.abs(middle - square.x) <= 12 || box.right >= innerWidth - 9),
      words: node?.textContent ?? "",
    };
  }, id, tip, square);
  seen.scrolls = during.filter(([index, over, sideways]) => sideways || over > (before[index]?.[1] ?? 0) + 1).map(([, , , name]) => name);
  await t.page.mouse.move(8, 8, { steps: 3 });
  await t.sleep(250);
  const hidden = await t.page.evaluate((id, tip) => {
    const node = document.querySelector(`[data-card-id="${id}"] ${tip}`);
    return !node || (!node.matches(":popover-open") && (node.hidden || getComputedStyle(node).display === "none"));
  }, id, tip);
  return { ...seen, hidden };
}
// The page sampled a frame at a time for `ms`: `read` (run in the page, the pointer's last x as window.__pointerX)
// each frame; awaiting what this gives waits the time out and gives [[time, value]…].
async function sampleFrames(t, read, ms) {
  await t.page.evaluate((body, ms) => {
    const read = new Function(`return (${body})()`);
    if (!window.__pointerWatched) {
      window.__pointerWatched = true;
      addEventListener("pointermove", (event) => { window.__pointerX = event.clientX; }, { capture: true, passive: true });
    }
    window.__pointerX = null;
    const samples = (window.__frames = []);
    const start = performance.now();
    const tick = () => {
      samples.push([performance.now(), read()]);
      if (performance.now() - start < ms) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }, read.toString(), ms);
  return async () => {
    await t.sleep(ms + 150);
    return t.page.evaluate(() => window.__frames);
  };
}
// Card `id` dragged by its grip, the pointer `dx`, `dy` from where it pressed; released unless `drop` is false.
async function dragGrip(t, id, dx, dy, { drop = true } = {}) {
  await hoverCard(t, id);
  const grip = await boxOf(t, ".ge-board-grip");
  await t.page.mouse.move(grip.cx, grip.cy);
  await t.page.mouse.down();
  await t.page.mouse.move(grip.cx + 6, grip.cy + 3, { steps: 2 });
  await t.page.mouse.move(grip.cx + dx, grip.cy + dy, { steps: 10 });
  await t.sleep(100);
  if (!drop) return;
  await t.page.mouse.up();
  await t.sleep(300);
}
// Card `id` resized from its corner, the pointer `dx`, `dy` from where it pressed.
async function dragCorner(t, id, dx, dy) {
  await hoverCard(t, id);
  const corner = await boxOf(t, ".ge-board-resize");
  await t.page.mouse.move(corner.cx, corner.cy);
  await t.page.mouse.down();
  await t.page.mouse.move(corner.cx + Math.sign(dx) * 6, corner.cy + Math.sign(dy) * 6, { steps: 2 });
  await t.page.mouse.move(corner.cx + dx, corner.cy + dy, { steps: 10 });
  await t.sleep(100);
  await t.page.mouse.up();
  await t.sleep(300);
}
// Card `id`'s menu opened (a click on its grip).
async function openCardMenu(t, id) {
  await hoverCard(t, id);
  const grip = await boxOf(t, ".ge-board-grip");
  await t.page.mouse.click(grip.cx, grip.cy);
  await t.page.waitForSelector(".ge-pop-row", { timeout: 5000 });
}
// Each card of page.html `text`, by its id: "x,y,w,h" as its attributes say them.
function cellsIn(text) {
  const cells = {};
  for (const [tag] of text.matchAll(/<section class="gallery-card"[^>]*>/g)) {
    const value = (name) => tag.match(new RegExp(`\\s${name}="([^"]*)"`))?.[1];
    cells[value("data-card-id")] = ["x", "y", "w", "h"].map((axis) => value(`data-${axis}`)).join(",");
  }
  return cells;
}

async function pageReady(t, slug, timeout = 15000) {
  await t.page.waitForFunction((slug) => {
    const frame = document.querySelector("iframe.report-frame:not([data-pending])");
    return document.querySelectorAll("iframe.report-frame").length === 1 && frame?.getAttribute("src") === `/pages/${slug}` && frame.contentDocument?.documentElement?.hasAttribute("data-doc-ready");
  }, { timeout }, slug);
  await t.sleep(300);
}

// Gallery's own blocks `names` (today, todos…) added as gallery block add puts them in, waited for until
// the server's catalog has them all (the home page's scenarios: homePageNews, workspaceTodosLive…).
async function homeBlocks(t, names) {
  const root = path.join(t.root, "reports");
  for (const name of names) addShipped(root, shippedBlock(name));
  const ids = names.map((name) => `gallery/${name}`);
  const taken = async () => (await (await fetch(`${t.home()}__gallery/workspace/components`)).json()).packages.filter(({ id, state }) => ids.includes(id) && state !== "broken").length === ids.length;
  if (!(await waitFor(t, taken, 15000))) throw new Error(`the server took no ${ids.join(", ")}`);
}

// Gallery's own blocks for custom pages (src/packs/gallery/: today, note, static, countdown, habit) added as
// gallery block add puts them in, and a custom page `slug` made by gallery page new holding a card of
// each, written into its page.html as an Agent writes one, the dates of their data counted from `day`
// ([year, monthIndex, date], today by default): a note of two lines, a static card's list, a countdown to
// three days on ("发布"; one day on when a day is given), a habit done the two days before (and on the
// day, when one is given). Waits until the server's catalog has them. { today, inThree, remove() }.
async function shippedBoard(t, slug, { day = null } = {}) {
  const root = path.join(t.root, "reports");
  const names = ["today", "note", "static", "countdown", "habit"];
  for (const name of names) addShipped(root, shippedBlock(name));
  t.gallery("page", "new", slug, "块");
  const base = day ? new Date(day[0], day[1], day[2], 12) : new Date();
  const dayOf = (offset) => {
    const date = new Date(base.getFullYear(), base.getMonth(), base.getDate() + offset, 12);
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
  };
  const toCount = day ? 1 : 3;
  const counted = new Date(base.getFullYear(), base.getMonth(), base.getDate() + toCount);
  const json = (value) => `<script type="application/json">${JSON.stringify(value)}</script>`;
  const card = (id, x, y, w, h, inner) => `      <section class="gallery-card" data-card-id="${id}" data-x="${x}" data-y="${y}" data-w="${w}" data-h="${h}">\n        ${inner}\n      </section>\n`;
  const cards = card("today", 0, 0, 4, 2, '<div data-doc-component="gallery/today"></div>')
    + card("note", 4, 0, 4, 2, `<div data-doc-component="gallery/note">${json({ text: "第一行\n第二行" })}</div>`)
    + card("countdown", 8, 0, 2, 2, `<div data-doc-component="gallery/countdown">${json({ title: "发布", date: dayOf(toCount) })}</div>`)
    + card("habit", 0, 2, 4, 2, `<div data-doc-component="gallery/habit">${json({ name: "读书", days: [dayOf(-2), dayOf(-1), ...(day ? [dayOf(0)] : [])] })}</div>`)
    + card("static", 4, 2, 4, 2, '<div data-doc-component="gallery/static"><div><h3>标题</h3><ul><li>第一项</li><li>第三项</li></ul></div></div>');
  const file = path.join(root, "pages", slug, "page.html");
  await fs.writeFile(file, (await fs.readFile(file, "utf8")).replace(`<div class="gallery-board" data-board-id="main">\n`, (board) => board + cards));
  await waitFor(t, async () => {
    const said = await fetch(`${t.home()}__gallery/workspace/components`).then((answer) => answer.json()).catch(() => null);
    return names.every((name) => said?.packages?.some(({ id, state }) => id === `gallery/${name}` && state !== "disabled"));
  }, 10000);
  return {
    today: dayOf(0),
    inThree: `${counted.getFullYear()}年${counted.getMonth() + 1}月${counted.getDate()}日`,
    async remove() {
      await fs.rm(path.join(root, "pages", slug), { recursive: true, force: true });
      for (const name of names) await fs.rm(path.join(root, "components", "gallery", name), { recursive: true, force: true });
      await t.sleep(2500); // the catalog taken
    },
  };
}

