// A workspace as a week of use leaves it, for 柔光风格's cards (softPackCards), written while no server runs: the
// documents of SOFT_DOCUMENTS, their files' times that long ago, and a record of edits (.gallery/state/
// activity.json) since 2026-07-06, each day's edits drawn from a seeded random as the pack's mockup draws its
// own (more on weekdays, fewer on weekends, October's first week of holiday nearly none, now and then a day
// of none), shared between the reader and the Agent; `undo` takes the documents away again.
async function softWeek(root, { undo = false } = {}) {
  if (undo) {
    for (const [slug] of SOFT_DOCUMENTS) await fs.rm(path.join(root, slug), { recursive: true, force: true });
    return;
  }
  const now = Date.now();
  for (const [slug, title, icon, minutes, body] of SOFT_DOCUMENTS) {
    const folder = path.join(root, slug);
    await fs.mkdir(folder, { recursive: true });
    await fs.writeFile(path.join(folder, "doc.html"), `<!doctype html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>${title}</title>\n</head>\n<body>\n  <main class="doc-page" data-doc-id="${slug}">\n    <header class="doc-header">\n      <h1 class="doc-title">${title}</h1>\n    </header>\n${body}  </main>\n</body>\n</html>\n`);
    await fs.writeFile(path.join(folder, "doc.json"), `${JSON.stringify({ title, ...(icon ? { icon } : {}), description: "", type: "report" }, null, 2)}\n`);
    const when = new Date(now - minutes * 60_000);
    for (const file of ["doc.html", "doc.json"]) await fs.utimes(path.join(folder, file), when, when);
  }
  let seed = 11;
  const random = () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
  const two = (value) => String(value).padStart(2, "0");
  const days = {};
  const today = new Date();
  for (let date = new Date(2026, 6, 6, 12); date <= today; date.setDate(date.getDate() + 1)) {
    const weekend = date.getDay() === 0 || date.getDay() === 6;
    let edits = weekend ? Math.round(random() * random() * 14) : Math.round(6 + random() * 26);
    if (date.getMonth() === 9 && date.getDate() <= 7) edits = random() < 0.55 ? 0 : Math.round(random() * 8);
    if (random() < 0.07) edits = 0;
    const agent = Math.round(edits * (0.48 + random() * 0.24));
    const reader = edits - agent;
    const words = (count) => count * Math.round(70 + random() * 90);
    if (edits === 0) continue;
    const slug = SOFT_DOCUMENTS[Math.floor(random() * 6)][0];
    days[`${date.getFullYear()}-${two(date.getMonth() + 1)}-${two(date.getDate())}`] = { [slug]: { ...(reader > 0 ? { reader: [reader, words(reader)] } : {}), ...(agent > 0 ? { agent: [agent, words(agent)] } : {}) } };
  }
  const state = path.join(root, ".gallery", "state");
  await fs.mkdir(state, { recursive: true });
  await fs.writeFile(path.join(state, "activity.json"), `${JSON.stringify({ version: 1, since: "2026-07-06", days, seen: {} })}\n`);
}

// What softPackCards fakes in a page, run before its own scripts (page.evaluateOnNewDocument): `clock`, the
// time it is (a Date whose now is that, moving on from it); `workspace`, the workspace's answers by kind (the
// query route's; "*" any other): "offline" (no answer, as a server that is not there: the kit's code
// "offline"), "failed" (a read the server could not do), or the data it answers; `net`, the weather's fetches
// refused by its city (联网: for its consent, its two hosts; 断网: offline; 私网: the network setup's address, "private").
function softFake(fake) {
  if (fake.clock) {
    const Real = Date;
    const shift = fake.clock - Real.now();
    globalThis.Date = class extends Real {
      constructor(...given) {
        if (given.length === 0) super(Real.now() + shift);
        else super(...given);
      }
      static now() {
        return Real.now() + shift;
      }
    };
  }
  if (fake.workspace) {
    const real = globalThis.fetch;
    const answer = (status, body) => Promise.resolve(new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } }));
    globalThis.fetch = function (input, init) {
      const address = new URL(String(input?.url ?? input), location.href);
      const said = address.pathname === "/__gallery/workspace/query" ? fake.workspace[address.searchParams.get("kind")] ?? fake.workspace["*"] : undefined;
      if (said === "offline") return Promise.reject(new TypeError("Failed to fetch"));
      if (said === "failed") return answer(500, { ok: false, reason: "read", message: "the scenario's" });
      if (said !== undefined) return answer(200, { ok: true, data: said, at: new Date().toISOString() });
      return real.call(this, input, init);
    };
  }
  if (fake.net) {
    const refusals = { 联网: { ok: false, code: "consent", hosts: ["api.open-meteo.com", "geocoding-api.open-meteo.com"] }, 断网: { ok: false, code: "offline" }, 私网: { ok: false, code: "private", host: "api.open-meteo.com" } };
    addEventListener("doc-net-fetch", (event) => {
      let city = null;
      try {
        city = new URL(event.detail.ask.url).searchParams.get("name");
      } catch {}
      if (!refusals[city]) return;
      event.stopImmediatePropagation();
      event.preventDefault();
      event.detail.answer(Promise.resolve(refusals[city]));
    }, true);
  }
}

// What Open-Meteo answers softPackCards' weather (its site, by the address's path): Shanghai found, its
// weather now (16°, partly cloudy, 72% humid) and five days ahead from today.
function softWeather() {
  const two = (value) => String(value).padStart(2, "0");
  const days = Array.from({ length: 5 }, (_, at) => {
    const date = new Date();
    date.setDate(date.getDate() + at);
    return `${date.getFullYear()}-${two(date.getMonth() + 1)}-${two(date.getDate())}`;
  });
  return {
    search: { results: [{ name: "上海", latitude: 31.22222, longitude: 121.45806, country: "中国", admin1: "上海" }] },
    "/https/api.open-meteo.com/v1/forecast": {
      current: { time: `${days[0]}T14:00`, temperature_2m: 16.2, apparent_temperature: 15.1, relative_humidity_2m: 72, wind_speed_10m: 11.4, weather_code: 2, is_day: 1 },
      daily: { time: days, weather_code: [2, 61, 3, 0, 1], temperature_2m_max: [19, 17, 15, 18, 19], temperature_2m_min: [12, 13, 11, 10, 11] },
    },
  };
}

// What a gallery command that fails says (its output, which runScript throws with), or "" when it did not fail.
function galleryFails(t, ...args) {
  try {
    t.gallery(...args);
    return "";
  } catch (error) {
    return error.message;
  }
}

