// A workbench page of the studio's origin with the report in an iframe, and the session messages
// the report sends it (docs/workbench.md), under the protocol id `protocol` (a workbench of the
// version before the product's rename speaks "html-report-studio/session" alone): `all` holds every
// message of the protocol under either id, as it came.
const WORKBENCH = (protocol) => `<!doctype html><meta charset="utf-8"><title>workbench</title>
<body style="margin:0"><iframe style="width:1240px;height:880px;border:0"></iframe>
<script>
  window.messages = [];
  window.all = [];
  addEventListener("message", (event) => {
    if (event.source !== document.querySelector("iframe").contentWindow) return;
    if (["gallery/session", "html-report-studio/session"].includes(event.data?.protocol)) all.push(event.data);
    if (event.data?.protocol !== ${JSON.stringify(protocol)}) return;
    messages.push(event.data);
    // The least a workbench does when asked to show the report again (the real one swaps a page in).
    if (event.data.type === "reload") event.source.location.reload();
  });
</script>`;

async function openWorkbench(t, slug = "sample", { protocol = "gallery/session" } = {}) {
  const { page } = t;
  const report = t.url(slug);
  const shell = new URL("/__test-workbench.html", report).href;
  page.workbenchBody = WORKBENCH(protocol); // the shell of this call, also when one was opened before in the scenario
  if (!page.workbenchServed) {
    page.workbenchServed = true;
    await page.setRequestInterception(true);
    page.on("request", (request) => {
      if (request.isInterceptResolutionHandled()) return;
      if (request.url() === shell) request.respond({ status: 200, contentType: "text/html; charset=utf-8", body: page.workbenchBody });
      else request.continue();
    });
  }
  await page.goto(shell, { waitUntil: "load" });
  await page.evaluate((src) => { document.querySelector("iframe").src = src; }, report);
  let sent = 0;
  const w = {
    frame: () => page.frames().find((frame) => frame.url().startsWith(report)),
    mark: () => page.evaluate(() => messages.length),
    last: () => page.evaluate(() => messages.at(-1)),
    // The first message of `type` from index `from` on.
    async next(type, from = 0) {
      const handle = await page.waitForFunction((type, from) => messages.slice(from).find((message) => message.type === type), { timeout: 20000 }, type, from);
      return handle.jsonValue();
    },
    // The first state (or ready) message that satisfies `test`, or null.
    async state(test, timeout = 8000) {
      const until = Date.now() + timeout;
      while (Date.now() < until) {
        const found = (await page.evaluate(() => messages)).find((message) => (message.type === "state" || message.type === "ready") && test(message));
        if (found) return found;
        await t.sleep(100);
      }
      return null;
    },
    messages: () => page.evaluate(() => messages),
    all: () => page.evaluate(() => all),
    async command(name, fields = {}) {
      const id = `c${++sent}`;
      await page.evaluate((message) => document.querySelector("iframe").contentWindow.postMessage(message, location.origin), { protocol, v: 2, type: "command", id, name, slug, ...fields });
      const handle = await page.waitForFunction((id) => messages.find((message) => message.type === "reply" && message.id === id), { timeout: 90000 }, id);
      await t.sleep(100);
      return handle.jsonValue();
    },
    // Whether a message that is not the protocol's got an answer.
    async answered(message) {
      const id = `x${++sent}`;
      await page.evaluate((message) => document.querySelector("iframe").contentWindow.postMessage(message, location.origin), { ...message, id });
      await t.sleep(400);
      return page.evaluate((id) => messages.some((message) => message.id === id), id);
    },
  };
  await page.waitForFunction(() => document.querySelector("iframe").contentDocument?.querySelector("[data-doc-ready]"), { timeout: 20000 });
  return w;
}

